 savedAddresses:@js($addresses->map(fn($a)=>$a->only(['id','name','phone','division_id','district_id','upazila_id','area_id','area','line1']))),
 addressBusy:false, async useAddress(id){let a=this.savedAddresses.find(a=>String(a.id)===String(id));if(!a)return;this.addressBusy=true;this.failure='';try{this.division=String(a.division_id);await this.divisionChanged();this.district=String(a.district_id);await this.districtChanged();this.upazila=String(a.upazila_id);await this.upazilaChanged();this.area=a.area_id?String(a.area_id):'';for(let [key,value] of Object.entries({name:a.name,phone:a.phone,address:a.line1,area:a.area||''})){this.$root.elements.namedItem(key).value=value;}}catch(e){this.failure=e.message}finally{await this.$nextTick();this.addressBusy=false}},
 step:1, steps:@js(store_setting('checkout_mode','one_page')==='steps'),
 nextStep(){let fields=[...this.$root.querySelectorAll('[data-checkout-step]')].filter(section=>Number(section.dataset.checkoutStep)===this.step).flatMap(section=>[...section.querySelectorAll('input,select,textarea')]);for(let field of fields){if(!field.checkValidity()){field.reportValidity();return}}this.step=Math.min(3,this.step+1)},
 division:@js((string)old('division_id','')), district:@js((string)old('district_id','')), upazila:@js((string)old('upazila_id','')), shipping:@js((string)old('shipping_method_id','')), gift:@js((bool)old('is_gift',false)), districts:[], upazilas:[], areas:[], area:@js((string)old('area_id','')), methods:[], totals:null, busy:false, failure:'',
 async children(parent){let r=await fetch('{{ route('locations.children') }}?parent='+encodeURIComponent(parent));if(!r.ok)throw Error(@js(__('checkout.load_failed')));return r.json()},
 async divisionChanged(){this.district='';this.upazila='';this.shipping='';this.totals=null;this.upazilas=[];this.areas=[];this.area='';this.methods=[];try{this.districts=await this.children(this.division)}catch(e){this.failure=e.message}},
 async upazilaChanged(){this.area='';this.areas=await this.children(this.upazila)},
 async districtChanged(){this.areas=[];this.area='';this.upazila='';this.shipping='';this.totals=null;try{this.upazilas=await this.children(this.district);let r=await fetch('{{ route('locations.shipping') }}?district='+encodeURIComponent(this.district));if(!r.ok)throw Error(@js(__('checkout.load_failed')));this.methods=await r.json()}catch(e){this.failure=e.message}},
 async quote(){if(this.shipping==='')return;this.busy=true;this.failure='';try{let r=await fetch('{{ route('checkout.quote') }}',{method:'POST',headers:{'Content-Type':'application/json','Accept':'application/json','X-CSRF-TOKEN':this.$refs.csrf.value},body:JSON.stringify({country:'BD',district_id:Number(this.district),shipping_method_id:Number(this.shipping),is_gift:this.gift})});let body=await r.json();if(!r.ok)throw Error(Object.values(body.errors||{}).flat().join(' '));this.totals=body}catch(e){this.failure=e.message;this.totals=null}finally{this.busy=false}},
 money(value){return new Intl.NumberFormat(@js(app()->getLocale()==='bn'?'bn-BD':'en-BD'),{style:'currency',currency:@js(config('checkout.base_currency'))}).format(value/100)},
 async init(){if(this.division){this.districts=await this.children(this.division)}if(this.district){this.upazilas=await this.children(this.district);let r=await fetch('{{ route('locations.shipping') }}?district='+this.district);this.methods=await r.json();if(this.shipping!=='')await this.quote()}if(this.upazila){this.areas=await this.children(this.upazila)}}
}">
